js='''\nconst bbPrices={small:{monthly:499,setup:499},premium:{monthly:999,setup:999},enterprise:{monthly:1999,setup:1999}},bbRate=.20;
function bbRead(){const d={small:0,premium:0,enterprise:0};document.querySelectorAll('.bb-qty').forEach(i=>{const v=Math.max(0,Math.floor(Number(i.value)||0));i.value=v;d[i.dataset.bbProduct]=v});return d}
function bbCalculate(){const d=bbRead();const baseByProduct={};let base=0,setupTotal=0;Object.keys(bbPrices).forEach(p=>{baseByProduct[p]=d[p]*bbPrices[p].monthly*bbRate;base+=baseByProduct[p];const sv=d[p]*bbPrices[p].setup*bbRate;setupTotal+=sv;document.getElementById('bbSetup'+p[0].toUpperCase()+p.slice(1)).textContent=eur(sv)});document.getElementById('bbSetupTotal').textContent=eur(setupTotal);const months=Array.from({length:60},(_,i)=>base*Math.min(i+1,12));document.getElementById('bbM1').textContent=eur(months[0]);document.getElementById('bbM6').textContent=eur(months[5]);document.getElementById('bbM12').textContent=eur(months[11]);const pcm=Object.values(d).reduce((a,b)=>a+b,0);document.getElementById('bbActive12').textContent=String(pcm*12);const years=[];for(let y=0;y<5;y++)years.push(months.slice(y*12,y*12+12).reduce((a,b)=>a+b,0));let cum=0;years.forEach((v,i)=>{cum+=v;document.getElementById('bbY'+(i+1)).textContent=eur(v);document.getElementById('bbC'+(i+1)).textContent=eur(cum)});document.getElementById('bbFiveTotal').textContent=eur(cum);Object.keys(baseByProduct).forEach(p=>document.getElementById('bbPt'+p[0].toUpperCase()+p.slice(1)).textContent=eur(baseByProduct[p]*654));const cumul=[];let run=0;years.forEach(v=>{run+=v;cumul.push(run)});const max=Math.max(...cumul,1);document.getElementById('bbYearBars').innerHTML=cumul.map((v,i)=>`<div class="year-bar-col"><b>${eur(v)}</b><div class="year-bar" style="height:${Math.max(2,v/max*100)}%"></div><span>Jahr ${i+1}</span></div>`).join('');document.getElementById('bbExplain').textContent=pcm===0?'Trage deine eigenen monatlichen Neuabschlüsse ein. Dieser Rechner startet bei 0 und rechnet keine Teamprovisionen hinzu.':`Bei ${pcm} neuen eigenen BusinessBooster-Verträgen pro Monat erreicht das Modell in Monat 12 rechnerisch ${pcm*12} gleichzeitig laufende Verträge. Die laufende Monatsprovision beträgt dann ${eur(months[11])}. Über fünf Jahre ergeben sich ${eur(cum)} laufende Eigenumsatz-Provision – ohne Setup, ohne Teamprovision und ohne unterstellte Verlängerung.`}
document.querySelectorAll('.bb-qty').forEach(i=>i.addEventListener('input',bbCalculate));document.getElementById('bbCalcBtn').addEventListener('click',bbCalculate);document.getElementById('bbResetBtn').addEventListener('click',()=>{document.querySelectorAll('.bb-qty').forEach(i=>i.value=0);bbCalculate()});bbCalculate();\n'''
marker="setLang('de');\n})();"
if marker not in s: raise SystemExit('js marker missing')
s=s.replace(marker,"setLang('de');\n"+js+")();",1)
p.write_text(s)
